import{K as l,a as i,c as s,b as a,k as r,q as c,ac as n}from"./chunks/framework.BSuaGltH.js";const f=JSON.parse('{"title":"Excel 数据验证、条件格式与重复检查","description":"为部门状态建立下拉菜单，限制数量输入，用条件格式标记重复编号和异常金额，区分工作表保护、输入限制和数据校验。","frontmatter":{"title":"Excel 数据验证、条件格式与重复检查","description":"为部门状态建立下拉菜单，限制数量输入，用条件格式标记重复编号和异常金额，区分工作表保护、输入限制和数据校验。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · Excel 表格与数据分析","summary":"为部门状态建立下拉菜单，限制数量输入，用条件格式标记重复编号和异常金额，区分工作表保护、输入限制和数据校验。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":{"text":"Excel 文本清洗、日期与时间计算","link":"/tools/office/excel/text-date"},"next":{"text":"Excel 图表、趋势与数据表达","link":"/tools/office/excel/charts"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Excel 文本清洗、日期与时间计算","link":"/tools/office/excel/text-date"},"next":{"text":"Excel 图表、趋势与数据表达","link":"/tools/office/excel/charts"}},"headers":[],"relativePath":"tools/office/excel/validation.md","filePath":"tools/office/excel/validation.md"}'),h={name:"tools/office/excel/validation.md"},g=Object.assign(h,{setup(d){const t={path:"/tools/office/excel/validation",app:"Excel",title:"用下拉选项规范订单状态",steps:[{tab:"工作表标签",command:"加号",setting:"字典：待处理 / 已完成 / 已取消",anchor:"walkthrough-1",surface:"area"},{tab:"数据",command:"数据验证",setting:"允许：序列；来源：=StatusList",anchor:"walkthrough-2"},{tab:"数据",command:"数据验证",setting:"检查现有值；新增行后检查规则",anchor:"walkthrough-3"}]};return(p,e)=>{const o=l("OfficeGuide");return i(),s("div",null,[e[0]||(e[0]=a("h1",{id:"excel-数据验证、条件格式与重复检查",tabindex:"-1"},[r("Excel 数据验证、条件格式与重复检查 "),a("a",{class:"header-anchor",href:"#excel-数据验证、条件格式与重复检查","aria-label":'Permalink to "Excel 数据验证、条件格式与重复检查"'},"​")],-1)),e[1]||(e[1]=a("p",null,"数据验证减少输入失误，条件格式让问题更容易被看见。它们不能代替最终校验：复制粘贴、导入或脚本可能绕过或覆盖某些限制，因此应同时设计检查列。",-1)),c(o,{guide:t}),e[2]||(e[2]=n(`<h2 id="list" tabindex="-1">建立下拉选项 <a class="header-anchor" href="#list" aria-label="Permalink to &quot;建立下拉选项 {#list}&quot;">​</a></h2><p>在新建的 <code>字典</code> 工作表 A1:A3 输入“已完成、待处理、已取消”，每个值占一个单元格。通过“公式 → 定义名称”把该区域命名为 <code>StatusList</code>。然后选中订单状态数据区域 G2:G9，打开“数据 → 数据验证”，允许“序列”，来源输入 <code>=StatusList</code>。</p><p>跨工作表来源使用命名区域较容易维护。更新选项时检查命名区域是否包含新增行；不要在每个单元格分别手写不同的选项。部门也可以用同样方式设置，防止同时出现“财务”“财务部”等非标准值。</p><h2 id="limits" tabindex="-1">限制数量与日期 <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;限制数量与日期 {#limits}&quot;">​</a></h2><p>对数量列 E2:E9 设置允许整数、介于 1 和 1000，并在输入信息中写“请输入正整数数量”。错误警告使用停止类型时可阻止普通直接输入不符合规则的值；范围应根据实际业务定义，退货数量允许负数时不能照搬本例。</p><p>日期列可设定起止范围，金额列可限制非负数。业务校验应比格式校验更明确：例如截止日期应不早于开始日期，这通常需要自定义公式或检查列，而不是仅把两列都设为日期。</p><h2 id="duplicates" tabindex="-1">用条件格式标记重复编号 <a class="header-anchor" href="#duplicates" aria-label="Permalink to &quot;用条件格式标记重复编号 {#duplicates}&quot;">​</a></h2><p>选中 A2:A9，使用“开始 → 条件格式 → 突出显示单元格规则 → 重复值”。需要整行标记时，选中 A2:H9，建立“使用公式确定要设置格式的单元格”的规则：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=AND($A2&lt;&gt;&quot;&quot;,COUNTIF($A$2:$A$9,$A2)&gt;1)</span></span></code></pre></div><p>公式以选区左上角 A2 为参照，固定 A 列而允许行变化。若把 <code>$A2</code> 写成 <code>$A$2</code>，每一行都只检查第一条订单。应用范围扩大时也要确认 COUNTIF 检查的总范围同步扩大。</p><h2 id="format" tabindex="-1">异常与状态提示 <a class="header-anchor" href="#format" aria-label="Permalink to &quot;异常与状态提示 {#format}&quot;">​</a></h2><p>可给已取消订单添加淡灰背景，给金额大于等于 1000 的记录加醒目边框；同时保留状态文字和金额，不单靠红绿颜色传达信息。打开“条件格式 → 管理规则”，检查规则顺序、应用区域和“如果为真则停止”，避免多条规则互相覆盖。</p><p>公式检查列比颜色更容易汇总，例如：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=IF(COUNTIF(Sales[订单号],[@订单号])&gt;1,&quot;重复编号&quot;,&quot;&quot;)</span></span>
<span class="line"><span>=IF(COUNTIF(StatusList,[@状态])=0,&quot;状态无效&quot;,&quot;&quot;)</span></span></code></pre></div><p>空值是否允许应单独定义；这两式不自动完成所有必填检查。</p><h2 id="protection" tabindex="-1">保护公式与输入区 <a class="header-anchor" href="#protection" aria-label="Permalink to &quot;保护公式与输入区 {#protection}&quot;">​</a></h2><p>默认单元格的“锁定”属性需要启用工作表保护后才生效。先选中允许填写的区域，在单元格格式的保护选项取消锁定，再“审阅 → 保护工作表”，允许需要的选择或筛选操作。保存前测试正常输入和公式区修改是否符合预期。</p><p>工作表保护主要防止误改，不应当作机密数据的安全边界。敏感数据需要文件访问权限或适当的文件加密；隐藏工作表和隐藏列也不能阻止获授权打开文件的人获取数据。</p><h2 id="practice" tabindex="-1">练习与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与验收 {#practice}&quot;">​</a></h2><p>输入状态“完成了”和数量 0，检查直接输入时是否被提示。把 O002 改成 O001，两个重复编号应被标记；再通过复制粘贴测试限制是否仍有效，并查看检查列是否能发现问题。恢复原始八条数据，确认没有异常提示。</p><h2 id="walkthrough" tabindex="-1">图示跟做：用下拉选项规范订单状态 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：用下拉选项规范订单状态 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：准备可维护的选项来源 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：准备可维护的选项来源 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：工作表标签 → 加号。</strong></p><p>新建字典表，在 A1:A3 放待处理、已完成、已取消，不加空白行。选中该区域，在名称框定义名称 StatusList。随后回到订单副本，选中 G2:G9；不要把表头 G1 也设为一个状态输入格。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：建立下拉并设置错误提示 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：建立下拉并设置错误提示 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：数据 → 数据验证。</strong></p><p>选择“数据 → 数据验证”，允许选序列，来源输入 =StatusList，启用单元格内下拉。错误警告使用停止，并写清允许输入的状态。点击一个状态格的下拉箭头，应该只有三个选项；手工输入“完成了”应被阻止。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：验证规则不会被粘贴绕过 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：验证规则不会被粘贴绕过 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：数据 → 数据验证。</strong></p><p>对已有数据做一次检查，再追加一行测试数据，确认验证是否延续到新行。复制粘贴可能带入不符合规则的值或覆盖规则，所以还应通过筛选和核对列检查整列状态。测试结束删去仅为验证新增的练习行，保留原八条订单。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>数据验证是录入辅助，不是权限控制，也不能替代数据质量检查。保护工作表前先区分可编辑区域与公式区域，解锁输入格后再测试用户能否正常填写。</p>`,33))])}}});export{f as __pageData,g as default};
